const RPC=SUPA+'/rest/v1/rpc/';
const $=id=>document.getElementById(id);
const fmt=n=>Number(n||0).toLocaleString();
const money=n=>n==null||n===''?'—':new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n)||0);
