const headers={'apikey':KEY,'Content-Type':'application/json','Accept':'application/json','Cache-Control':'no-cache'};
async function rpc(name,args={},timeout=5000){const c=new AbortController(),t=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(RPC+name,{method:'POST',headers,body:JSON.stringify(args),signal:c.signal,cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d?.message||d?.error||('HTTP '+r.status));return d}finally{clearTimeout(t)}}

const AUTH_STORE='bp_auth_v5045';let authSession=null,workspaceLast=null,packageCatalogLast=null,workspaceLoading=null,pendingPackageKey=null;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function saveSession(s){authSession=s||null;if(s)localStorage.setItem(AUTH_STORE,JSON.stringify(s));else localStorage.removeItem(AUTH_STORE);renderAuthState()}
function sessionExpiry(s){return Number(s?.expires_at||0)*1000}
async function authExchange(path,body){const r=await fetch(SUPA+'/auth/v1/'+path,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(body),cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d?.msg||d?.message||d?.error_description||d?.error||('HTTP '+r.status));if(d?.access_token){if(!d.expires_at&&d.expires_in)d.expires_at=Math.floor(Date.now()/1000)+Number(d.expires_in);saveSession(d)}return d}
async function refreshAuth(){if(!authSession?.refresh_token)return null;try{return await authExchange('token?grant_type=refresh_token',{refresh_token:authSession.refresh_token})}catch(e){saveSession(null);throw e}}
async function ensureAuth(){if(!authSession){try{authSession=JSON.parse(localStorage.getItem(AUTH_STORE)||'null')}catch(_){authSession=null}}if(authSession?.access_token&&sessionExpiry(authSession)-Date.now()<90000&&authSession.refresh_token)await refreshAuth();return authSession?.access_token?authSession:null}
async function authRpc(name,args={},timeout=9000,retry=true){const s=await ensureAuth();if(!s)throw new Error('SIGN_IN_REQUIRED');const c=new AbortController(),t=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(RPC+name,{method:'POST',headers:{...headers,Authorization:'Bearer '+s.access_token},body:JSON.stringify(args),signal:c.signal,cache:'no-store'}),d=await r.json().catch(()=>({}));if(r.status===401&&retry&&s.refresh_token){clearTimeout(t);await refreshAuth();return authRpc(name,args,timeout,false)}if(!r.ok)throw new Error(d?.message||d?.error||('HTTP '+r.status));return d}finally{clearTimeout(t)}}
function openAuth(message=''){if($('authPanel'))$('authPanel').hidden=false;if(message)setText('authMessage',message)}function closeAuth(){if($('authPanel'))$('authPanel').hidden=true}
function renderAuthState(){const signed=!!authSession?.access_token,email=authSession?.user?.email||'Signed-in BridgePoint account';if($('authSignedOut'))$('authSignedOut').hidden=signed;if($('authSignedIn'))$('authSignedIn').hidden=!signed;setText('authUserEmail',email);if($('accountButton'))$('accountButton').textContent=signed?'ACCOUNT ✓':'ACCOUNT';if(!signed)setText('authAccessSummary','Sign in to load access')}
async function restoreAuth(){try{authSession=JSON.parse(localStorage.getItem(AUTH_STORE)||'null')}catch(_){authSession=null}if(authSession?.access_token){try{await ensureAuth()}catch(_){}}renderAuthState()}
async function signIn(email,password){setText('authMessage','Signing in…');await authExchange('token?grant_type=password',{email,password});setText('authMessage','');await loadWorkspace(true);if(pendingPackageKey){const pk=pendingPackageKey;pendingPackageKey=null;await handlePackageAction(pk)}}
async function createAccount(email,password){setText('authMessage','Creating account…');const d=await authExchange('signup',{email,password});if(d?.access_token){setText('authMessage','Account created and signed in.');await loadWorkspace(true)}else setText('authMessage','Account created. Check your email if confirmation is required, then sign in.')}
async function signOut(){try{const s=await ensureAuth();if(s)await fetch(SUPA+'/auth/v1/logout',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+s.access_token}})}catch(_){}saveSession(null);workspaceLast=null;renderWorkspaceSignedOut();renderPackages();closeAuth()}
function toast(msg,kind='info'){const t=$('accessToast');if(!t)return;t.textContent=msg;t.dataset.kind=kind;t.hidden=false;clearTimeout(t.__timer);t.__timer=setTimeout(()=>t.hidden=true,5200)}
function renderSignedOutBox(id,label){const h=$(id);if(!h)return;h.className='empty-state';h.innerHTML='<b>'+esc(label)+'</b><p>Sign in to load this BridgePoint workspace.</p><button type="button" class="inline-auth">SIGN IN</button>';h.querySelector('button')?.addEventListener('click',()=>openAuth())}
function renderWorkspaceSignedOut(){renderSignedOutBox('savedWorkspace','Saved intelligence is account-based.');renderSignedOutBox('claimsWorkspace','Claims intelligence is account-based and package-gated.');renderSignedOutBox('workflowWorkspace','Workflow actions are account-based.')}
function packageActiveSet(){return new Set((workspaceLast?.access?.packages||[]).map(p=>p.package_key))}
function packagePrice(p){const m=Number(p.monthly_price||0),y=Number(p.yearly_price||0);return m>0?money(m)+'/mo'+(y>0?' · '+money(y)+'/yr':''):y>0?money(y)+'/yr':'Contact BridgePoint'}
function packageActionLabel(p,a){if(a)return'ACTIVE';if(p.owner_approval_required)return'REQUEST ACCESS';if(p.purchase_mode==='IMMEDIATE'&&Number(p.trial_days||0)>0&&p.delivery_status==='READY')return'START '+p.trial_days+'-DAY TRIAL';if(p.delivery_status==='BUILDING')return'EARLY ACCESS INFO';if(p.delivery_status==='ROADMAP')return'ROADMAP';return'ACCESS DETAILS'}
function renderPackages(){const h=$('packagesGrid'),rows=Array.isArray(packageCatalogLast?.packages)?packageCatalogLast.packages:[],active=packageActiveSet();if(!h)return;h.textContent='';if(!rows.length){h.innerHTML='<div class="empty-state">Package catalog is temporarily unavailable.</div>';return}const customer=rows.filter(p=>!String(p.package_key||'').startsWith('technology_')),tech=rows.filter(p=>String(p.package_key||'').startsWith('technology_')),head=t=>{const x=document.createElement('h2');x.className='grid-section-title';x.textContent=t;h.appendChild(x)},add=p=>{const c=document.createElement('article');c.className='page-card package-card';const on=active.has(p.package_key);c.innerHTML='<span>'+esc((p.package_type||'PACKAGE').toUpperCase())+' · '+esc(p.delivery_status||'')+'</span><h3>'+esc(p.package_name||p.package_key)+'</h3><p>'+esc(p.description||'BridgePoint intelligence access.')+'</p><div class="package-price">'+esc(packagePrice(p))+'</div><div class="package-meta">'+(Number(p.trial_days||0)>0?esc(p.trial_days+'-day trial'):'No automatic trial')+' · '+esc((p.purchase_mode||'ACCESS').replaceAll('_',' '))+'</div><button type="button" '+(on?'disabled':'')+'>'+esc(packageActionLabel(p,on))+'</button>';c.querySelector('button')?.addEventListener('click',()=>handlePackageAction(p.package_key));h.appendChild(c)};head('Customer intelligence');customer.forEach(add);if(tech.length){head('Technology & enterprise');tech.forEach(add)}}
async function loadPackageCatalog(){try{packageCatalogLast=await rpc('bridgepoint_public_package_catalog_v1054',{},6500);renderPackages()}catch(e){console.warn('package catalog',e);renderPackages()}}
async function handlePackageAction(pk){const p=(packageCatalogLast?.packages||[]).find(x=>x.package_key===pk);if(!p)return;if(!authSession?.access_token){pendingPackageKey=pk;openAuth('Sign in to choose '+p.package_name+'.');return}setText('packageActionStatus','Processing '+p.package_name+'…');try{const d=await authRpc('bridgepoint_package_action_v5045',{p_package_key:pk,p_note:'Requested from rebuilt BridgePoint Intelligence app'},12000);toast(d.message||'Access request saved.','success');setText('packageActionStatus',d.message||'Access updated.');await loadWorkspace(true)}catch(e){toast(String(e.message||e),'error');setText('packageActionStatus','Access action failed · '+String(e.message||e))}}
const rows=(o,k)=>Array.isArray(o?.[k])?o[k]:[];
function renderSaved(){const h=$('savedWorkspace');if(!h)return;if(!workspaceLast){renderSignedOutBox('savedWorkspace','Saved intelligence is account-based.');return}const a=rows(workspaceLast.saved,'saved_opportunities'),w=rows(workspaceLast.watchlists,'watchlists');h.className='workspace-list';h.innerHTML='<div class="workspace-summary"><b>'+fmt(a.length)+' saved opportunities</b><span>'+fmt(w.length)+' watchlists</span></div>';if(!a.length&&!w.length){h.innerHTML+='<div class="empty-state">Nothing saved yet. Save an eligible property or opportunity from the map and it will appear here.</div>';return}for(const r of a){const e=document.createElement('article');e.className='workspace-row';e.innerHTML='<span>'+esc(r.vertical_key||r.lead_stage||'SAVED')+'</span><h3>'+esc(r.title||r.address||'Saved opportunity')+'</h3><p>'+esc(r.address||'')+'</p><small>'+esc([r.lead_stage,r.next_action_at?new Date(r.next_action_at).toLocaleString():null].filter(Boolean).join(' · '))+'</small>';h.appendChild(e)}for(const r of w){const e=document.createElement('article');e.className='workspace-row compact';e.innerHTML='<span>WATCHLIST</span><h3>'+esc(r.name||'Watchlist')+'</h3><p>'+fmt(r.item_count||0)+' items</p>';h.appendChild(e)}}
function renderClaims(){const h=$('claimsWorkspace');if(!h)return;if(!workspaceLast){renderSignedOutBox('claimsWorkspace','Claims intelligence is account-based and package-gated.');return}const a=rows(workspaceLast.claims,'claims'),e=rows(workspaceLast.claims,'eligible_saved_opportunities');h.className='workspace-list';h.innerHTML='<div class="workspace-summary"><b>'+fmt(a.length)+' claims</b><span>'+fmt(e.length)+' eligible saved items</span></div>';if(!a.length){h.innerHTML+='<div class="empty-state">No claims yet. Claims start from eligible saved opportunities; customer-entered claim data stays separate from source evidence.</div>';return}for(const r of a){const x=document.createElement('article');x.className='workspace-row';x.innerHTML='<span>'+esc(r.claim_stage||'CLAIM')+'</span><h3>'+esc(r.title||r.address||r.claim_number||'Claim')+'</h3><p>'+esc([r.carrier_name,r.damage_type,r.claim_number].filter(Boolean).join(' · '))+'</p><small>'+fmt((r.open_tasks||[]).length)+' open tasks'+(r.next_action_at?' · next '+esc(new Date(r.next_action_at).toLocaleString()):'')+'</small>';h.appendChild(x)}}
function renderWorkflow(){const h=$('workflowWorkspace');if(!h)return;if(!workspaceLast){renderSignedOutBox('workflowWorkspace','Workflow actions are account-based.');return}const a=[...rows(workspaceLast.saved,'saved_opportunities')].sort((x,y)=>new Date(x.next_action_at||'9999-12-31')-new Date(y.next_action_at||'9999-12-31'));h.className='workspace-list';h.innerHTML='<div class="workspace-summary"><b>'+fmt(a.length)+' tracked actions</b><span>Saved opportunity pipeline</span></div>';if(!a.length){h.innerHTML+='<div class="empty-state">Save an opportunity to start a BridgePoint workflow.</div>';return}for(const r of a){const x=document.createElement('article');x.className='workspace-row';x.innerHTML='<span>'+esc(r.lead_stage||'SAVED')+'</span><h3>'+esc(r.title||r.address||'Opportunity')+'</h3><p>'+esc(r.recommended_action||r.reason||'No next action recorded')+'</p><small>'+(r.next_action_at?'Next '+esc(new Date(r.next_action_at).toLocaleString()):'No due date')+'</small>';h.appendChild(x)}}
async function loadWorkspace(force=false){if(workspaceLoading&&!force)return workspaceLoading;const s=await ensureAuth();if(!s){workspaceLast=null;renderWorkspaceSignedOut();renderPackages();return null}workspaceLoading=(async()=>{try{workspaceLast=await authRpc('bridgepoint_my_workspace_v5045',{},15000);const p=workspaceLast?.access?.packages||[];setText('authAccessSummary',p.length?p.map(x=>x.package_name).join(' · '):(workspaceLast?.access?.platform_override?'Platform owner override':'No active package'));renderPackages();renderSaved();renderClaims();renderWorkflow();return workspaceLast}catch(e){console.warn('workspace',e);toast('Workspace retry · '+String(e.message||e),'error');return null}finally{workspaceLoading=null}})();return workspaceLoading}
