async function showPropertyOnly(lng,lat,opts={}){const seq=++buildingRequestSeq;clearMapXray();clearBuildingParts();selectedPoint={lng,lat};selectedFeature=null;selectedMode='property';const panel=$('buildingPanel');panel.hidden=false;if(innerWidth<=760)closeSystem();if(!opts.silent){setText('buildingTitle','Property');setText('buildingTruthBadge','PROPERTY IDENTITY');setText('bHeight','—');setText('bFloors','—');setText('bFloorTruth','—');setText('bParts','—');setText('bUnderground','—');setText('bConfidence','—');setText('bRoof','—');setText('bFacade','—');setText('bSource','—');setText('bSourceDate','No building selected');setText('bGeometryMeta','No building selected');setText('bGeometrySub','Parcel identity can resolve independently of a building.');resetPropertyCard();resetContext()}await waitForMapRest();if(seq!==buildingRequestSeq)return;queueAfterMap('property-context-'+seq,()=>loadContext(lng,lat,seq));queueAfterMap('property-foundation-'+seq,()=>loadFoundation(lng,lat,seq));await loadProperty(lng,lat,seq);if(!selectedTimer)selectedTimer=setInterval(refreshSelected,15000)}
