function prefillBuildingFromFeature(feature){if(!feature?.geometry)return;const p=feature.properties||{},id=p.building_id||feature.id||'mapped',h=Math.max(2.4,Number(p.render_height_m||p.height_m||p.height||8.5)),sourceFloors=Number(p.floors||0),floors=sourceFloors>0?sourceFloors:Math.max(1,Math.round(h/3.2)),conf=p.source_confidence!=null?Math.round(Number(p.source_confidence)*100):null,area=geometryAreaM2(feature.geometry),method=sourceFloors>0?'SOURCE_NUM_FLOORS':'HEIGHT_DIV_3_2M_ESTIMATE',base=Number(p.base_height_m||p.min_height_m||0);setText('buildingTitle','Building #'+id);setText('buildingTruthBadge',sourceFloors>0?'SOURCE-BACKED VERTICAL':'HEIGHT-DERIVED STRUCTURE');setText('bHeight',h.toFixed(1)+' m');setText('bFloors',String(floors));setText('bFloorTruth',sourceFloors>0?'source-backed':'derived from height');setText('bParts','Checking deeper source');setText('bUnderground','0 asserted');setText('bConfidence',conf!=null?conf+'%':'Not scored by source');setText('bRoof','Source detail loading');setText('bFacade','Source detail loading');setText('bSource',p.source_key||'BridgePoint public-safe building tile');setText('bSourceDate','Deeper source timestamp loading');setText('bBaseHeight',base.toFixed(1)+' m');setText('bFootprintArea',area!=null?area.toLocaleString(undefined,{maximumFractionDigits:1})+' m²':'Footprint geometry loaded');setText('bHeightEvidence',String(p.height_truth||'MAP_TILE_HEIGHT').replaceAll('_',' '));setText('bRoofHeight','Not published in tile');setText('bRoofDirection','Not published in tile');setText('bState',p.state_code||'State detail loading');setText('bRecord',String(p.source_record_id||id));setText('bProvSource',p.source_key||'BridgePoint public-safe building tile');setText('bProvDataset','BridgePoint public-safe building tile · deeper provenance loading');setText('bProvLicense','Deeper source license loading');setText('bProvOriginal',String(p.source_record_id||id));setText('bProvOriginalUpdated','Deeper source timestamp loading');setText('bProvVertical',(sourceFloors>0?'source-backed':'derived from height')+' · '+method);setText('bProvPlan','Checking exact lawful public-plan match');setText('bProvPolicy','PUBLIC_SAFE_MAP_PREFILL');setText('bProvUpdated','Deeper source timestamp loading');setText('bTruthNote','Immediate preview from the selected BridgePoint geometry. Deeper source evidence is loading and will replace these preview values; no room geometry is invented.');setText('bGeometryMeta',(feature.geometry.type||'Building')+' · clicked BridgePoint geometry');setText('bGeometrySub','Only this clicked building is selected. Deeper source evidence is loading.');drawFootprint(feature.geometry,0);ensureSelectedLayer(feature.geometry,{...p,render_height_m:h,base_height_m:base});applyMapXray(feature.geometry,{building_id:id,floors,render_height_m:h,base_height_m:base,floor_count_method:method})}

async function showBuilding(lng,lat,opts={}){const panel=$('buildingPanel'),seq=++buildingRequestSeq;selectedPoint={lng,lat};selectedFeature=opts.feature||selectedFeature;selectedMode='building';panel.hidden=false;const parcelSrc=world?.map?.getSource('bpV5001SelectedParcel');if(parcelSrc?.setData)parcelSrc.setData({type:'FeatureCollection',features:[]});resetPropertyCard();if(!opts.silent){resetContext();if(selectedFeature)prefillBuildingFromFeature(selectedFeature)}if(innerWidth<=760)closeSystem();if(!selectedTimer)selectedTimer=setInterval(refreshSelected,15000);await waitForMapRest();if(seq!==buildingRequestSeq)return;queueAfterMap('building-property-'+seq,()=>loadProperty(lng,lat,seq));queueAfterMap('building-context-'+seq,()=>loadContext(lng,lat,seq));queueAfterMap('building-foundation-'+seq,()=>loadFoundation(lng,lat,seq));try{const exactBuildingId=Number(selectedFeature?.properties?.building_id||selectedFeature?.id||0);let d=null,detailErr=null;if(exactBuildingId>0){try{d=await rpc('bridgepoint_public_building_detail_by_id_v5024',{p_building_id:exactBuildingId},7000)}catch(e){detailErr=e}}if(!d?.resolved){try{d=await rpc('bridgepoint_public_building_detail_v5000',{p_lng:lng,p_lat:lat,p_radius_m:140},6500)}catch(e){detailErr=detailErr||e}}if(seq!==buildingRequestSeq)return;if(!d&&detailErr)throw detailErr;if(!d?.resolved){setText('buildingTruthBadge',selectedFeature?'BRIDGEPOINT MAP BUILDING':'NO BUILDING RESOLVED');setText('bTruthNote',selectedFeature?'The clicked BridgePoint geometry is selected, but a deeper structural enrichment record is not linked yet. Tile evidence remains visible without inventing missing fields.':'BridgePoint did not resolve a public building geometry at this point yet.');return}const b=d.building||{};loadBuildingParts(b.building_id,seq);setText('buildingTitle','Building #'+b.building_id);setText('buildingTruthBadge',truthLabel(b));setText('bHeight',b.render_height_m?Number(b.render_height_m).toFixed(1)+' m':'—');setText('bFloors',b.floors??'—');setText('bFloorTruth',floorTruth(b.floor_count_method));setText('bParts',fmt(b.building_part_count));setText('bUnderground',b.underground_part_count?fmt(b.underground_part_count)+(b.max_underground_floors?' · '+b.max_underground_floors+' floors':''):'0');setText('bConfidence',b.source_confidence!=null?Math.round(Number(b.source_confidence)*100)+'%':'Not scored by source');setText('bRoof',[b.roof_shape,b.roof_material].filter(Boolean).join(' · ')||'Not published by source');setText('bFacade',b.facade_material||'Not published by source');setText('bSource',b.source_key||'BridgePoint source registry');setText('bSourceDate',sourceAge(b.source_updated_at));setText('bTruthNote',d.truth_notice||'BridgePoint labels derived structure separately from exact public plans.');populateInspector(b,selectedFeature?.geometry,selectedFeature?.properties)}catch(e){if(seq!==buildingRequestSeq)return;setText('buildingTruthBadge','DETAIL RETRY');setText('bTruthNote',e.message||String(e))}}
window.__BP_V5000_SELECT_BUILDING__=({lngLat,feature})=>{if(!lngLat)return false;lastDirectBuildingEvent=performance.now();const panel=$('buildingPanel');if(panel){panel.hidden=false;panel.style.display='block'}showBuilding(lngLat.lng,lngLat.lat,{feature});return true};let lastDirectBuildingEvent=0;window.addEventListener('bp2300:building-click',e=>{if(performance.now()-lastDirectBuildingEvent<250)return;const ll=e.detail?.lngLat,f=e.detail?.feature;if(ll)showBuilding(ll.lng,ll.lat,{feature:f})});
$('publicSearchForm').addEventListener('submit',async e=>{e.preventDefault();setMapSearchOpen(true);const q=$('publicSearchInput').value.trim(),box=$('publicSearchResults');if(q.length<4)return;box.hidden=false;box.innerHTML='<button disabled>Searching BridgePoint…</button>';try{const d=await rpc('bridgepoint_public_search_v5000',{p_query:q,p_limit:8},3500),rows=d?.results||[];if(!rows.length){box.innerHTML='<button disabled>No exact address match yet. Try the street address without city/state.</button>';return}box.innerHTML='';for(const r of rows){const b=document.createElement('button');b.type='button';b.innerHTML='<b>'+String(r.full_address||'Address').replace(/[<>&]/g,'')+'</b><small>'+[r.municipality,r.state_code,r.parcel_number].filter(Boolean).join(' · ')+'</small>';b.onclick=()=>{box.hidden=true;setMapSearchOpen(false);const lng=+r.longitude,lat=+r.latitude;if(world?.map&&Number.isFinite(lng)&&Number.isFinite(lat)){world.map.easeTo({center:[lng,lat],zoom:17,pitch:62,bearing:-18,duration:700});selectedFeature=null;showBuilding(lng,lat)}};box.appendChild(b)}}catch(err){box.innerHTML='<button disabled>Search retry · '+String(err.message||err).replace(/[<>&]/g,'')+'</button>'}});

function ensureLiveLegend(){let root=$('liveLegend');if(root)return root;root=document.createElement('div');root.id='liveLegend';root.className='live-legend';root.innerHTML='<div class="live-legend-head"><b>LIVE SOURCE CONTEXT</b><span id="liveLegendCount">CHECKING</span></div><div class="live-legend-items"><span class="live-legend-item"><i class="live-dot" style="color:#ff744f;background:#ff744f"></i>Wildfire</span><span class="live-legend-item"><i class="live-dot" style="color:#ffe16d;background:#ffe16d"></i>Lightning</span><span class="live-legend-item"><i class="live-dot" style="color:#4ca7ff;background:#4ca7ff"></i>Flood</span><span class="live-legend-item"><i class="live-dot" style="color:#d596ff;background:#d596ff"></i>Tornado</span><span class="live-legend-item"><i class="live-dot" style="color:#65e6ff;background:#65e6ff"></i>Hurricane</span></div><small id="liveLegendTime">Solid = observed/source event · faded = alert or forecast</small>';document.querySelector('.map-surface')?.appendChild(root);return root}

function liveFeaturePopup(map,e){const f=e.features?.[0];if(!f)return;const p=f.properties||{},wrap=document.createElement('div');wrap.style.cssText='min-width:210px;max-width:280px;font-family:Inter,system-ui,sans-serif;color:#071118';const kicker=document.createElement('div');kicker.style.cssText='font-size:9px;font-weight:900;letter-spacing:.08em;color:#397180';kicker.textContent=(p.observed===true||p.observed==='true'?'OBSERVED / SOURCE EVENT':'ALERT / FORECAST CONTEXT');const title=document.createElement('b');title.style.cssText='display:block;margin-top:4px;font-size:13px;line-height:1.2';title.textContent=String(p.name||p.type||'Live context');const meta=document.createElement('div');meta.style.cssText='margin-top:5px;font-size:10px;line-height:1.4;color:#415661';meta.textContent=[p.type?String(p.type).replaceAll('_',' '):null,p.severity||null,p.source||null].filter(Boolean).join(' · ');const time=document.createElement('div');time.style.cssText='margin-top:5px;font-size:9px;color:#607681';const observedAt=p.observed_at?new Date(p.observed_at):null;const endsAt=p.ends_at?new Date(p.ends_at):null;time.textContent=[observedAt&&Number.isFinite(observedAt.getTime())?'Observed '+observedAt.toLocaleString():null,endsAt&&Number.isFinite(endsAt.getTime())?'Ends '+endsAt.toLocaleString():null].filter(Boolean).join(' · ')||'Timestamp unavailable';wrap.append(kicker,title,meta,time);new maplibregl.Popup({closeButton:true,closeOnClick:true,maxWidth:'310px'}).setLngLat(e.lngLat).setDOMContent(wrap).addTo(map)}
function bindLiveContextInteraction(){const map=world?.map;if(!map||map.__bpV5009LiveBound)return;map.__bpV5009LiveBound=true;for(const id of ['bp-v5004-weather-points','bp-v5004-weather-shape-fill','bp-v5004-weather-shape-line']){map.on('click',id,e=>{try{const buildingLayers=['gta-opportunity-buildings','gta-exact-building','gta-bp-buildings'].filter(x=>map.getLayer(x));if(buildingLayers.length&&map.queryRenderedFeatures(e.point,{layers:buildingLayers}).length)return}catch(_){}e.originalEvent?.stopPropagation?.();liveFeaturePopup(map,e)});map.on('mouseenter',id,()=>{map.getCanvas().style.cursor='pointer'});map.on('mouseleave',id,()=>{map.getCanvas().style.cursor=''})}}


function ensurePmtilesProtocol(){if(!window.pmtiles?.Protocol||!window.maplibregl)return false;if(!window.__BP_PMTILES_PROTOCOL){const p=new window.pmtiles.Protocol({metadata:true});maplibregl.addProtocol('pmtiles',p.tile);window.__BP_PMTILES_PROTOCOL=p}return true}
