function ensureDCRuntimeTransportLayers(url){const map=world?.map;if(!map||!url||!ensurePmtilesProtocol())return;const sourceUrl='pmtiles://'+url;const before=map.getLayer('gta-bp-buildings')?'gta-bp-buildings':undefined;let src=map.getSource('bpTransportDC');if(!src){map.addSource('bpTransportDC',{type:'vector',url:sourceUrl,attribution:'© Overture Maps Foundation (ODbL 1.0) · BridgePoint verified v2696 archive'});map.addLayer({id:'bp-v2716-transport-casing',type:'line',source:'bpTransportDC','source-layer':'segments',minzoom:6,paint:{'line-color':'#07131a','line-opacity':.82,'line-width':['interpolate',['linear'],['zoom'],6,.35,10,1.2,14,3.6,18,8.5]}},before);map.addLayer({id:'bp-v2716-transport-segments',type:'line',source:'bpTransportDC','source-layer':'segments',minzoom:6,paint:{'line-color':['match',['downcase',['coalesce',['get','subtype'],'']],'rail','#9ba9b1','road','#b8d2dc','#89b7c6'],'line-opacity':['interpolate',['linear'],['zoom'],6,.30,10,.48,14,.72,18,.92],'line-width':['interpolate',['linear'],['zoom'],6,.16,10,.55,14,1.8,18,5.2]}},before);map.addLayer({id:'bp-v2716-transport-connectors',type:'circle',source:'bpTransportDC','source-layer':'connectors',minzoom:17,paint:{'circle-radius':['interpolate',['linear'],['zoom'],17,.6,20,1.8],'circle-color':'#dff8ff','circle-opacity':.45}},before)}else if(transportSourceUrl!==sourceUrl&&typeof src.setUrl==='function'){src.setUrl(sourceUrl)}transportSourceUrl=sourceUrl;setTransportVisibility(transportVisible);const b=$('toggleTransport');if(b){b.hidden=false;b.classList.toggle('active',transportVisible);b.title='BridgePoint runtime transport · DC pilot · derived from verified v2696 archive'}}
async function loadDCRuntimeTransport(){if(mapInteracting){deferredWork.set('runtime-transport',loadDCRuntimeTransport);return}try{const r=await fetch(SUPA+'/functions/v1/bridgepoint-transport-runtime-broker-v2716',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'public_runtime_url',state_code:'DC'}),cache:'no-store'});const d=await r.json();if(!r.ok||d?.complete===false)throw new Error(d?.error||('HTTP '+r.status));if(d?.available){ensureDCRuntimeTransportLayers(d.url);setText('transportRuntime','RUNTIME MATERIALIZING · DC LIVE · '+fmt(Number(d.segment_rows||0)+Number(d.connector_rows||0))+' rows')}else{const b=$('toggleTransport');if(b)b.hidden=true}}catch(e){console.warn('DC runtime transport',e)}}
