function weatherColorExpr(){return['match',['get','type'],'WILDFIRE','#ff744f','FIRE_WEATHER','#ff9c5a','TORNADO','#d596ff','HAIL','#c9efff','LIGHTNING','#ffe16d','FLOOD','#4ca7ff','HURRICANE','#65e6ff','HURRICANE_CONE','#65e6ff','HURRICANE_TRACK','#65e6ff','WIND','#9ad7ff','RAIN','#68b9ff','WEATHER_REPORT','#b9d6df','#9ab8c5']}
function liveLayerIds(){return['bp-v5004-weather-shape-fill','bp-v5004-weather-shape-line','bp-v5004-weather-point-glow','bp-v5004-weather-points']}
function setLiveContextVisibility(on){liveContextVisible=!!on;const map=world?.map;for(const id of liveLayerIds()){try{if(map?.getLayer(id))map.setLayoutProperty(id,'visibility',liveContextVisible?'visible':'none')}catch(_){}}const b=$('toggleLiveContext');if(b)b.classList.toggle('active',liveContextVisible);const legend=ensureLiveLegend();if(legend)legend.hidden=!liveContextVisible}
function weatherCollections(items){const points=[],shapes=[];for(const item of items||[]){const props={type:item.type||'WEATHER_REPORT',name:item.name||item.type||'Weather event',severity:item.severity||'',certainty:item.certainty||'',urgency:item.urgency||'',observed:item.observed===true,source:item.source||'',observed_at:item.observed_at||'',ends_at:item.ends_at||''};if(item.geometry&&item.geometry.type){shapes.push({type:'Feature',properties:props,geometry:item.geometry});continue}const lon=Number(item.lon),lat=Number(item.lat);if(Number.isFinite(lon)&&Number.isFinite(lat))points.push({type:'Feature',properties:props,geometry:{type:'Point',coordinates:[lon,lat]}})}return{points:{type:'FeatureCollection',features:points},shapes:{type:'FeatureCollection',features:shapes}}}
function installLiveContextLayers(){const map=world?.map;if(!map)return;const install=()=>{try{if(!map.getSource('bpV5004WeatherPoints'))map.addSource('bpV5004WeatherPoints',{type:'geojson',data:{type:'FeatureCollection',features:[]}});if(!map.getSource('bpV5004WeatherShapes'))map.addSource('bpV5004WeatherShapes',{type:'geojson',data:{type:'FeatureCollection',features:[]}});if(!map.getLayer('bp-v5004-weather-shape-fill'))map.addLayer({id:'bp-v5004-weather-shape-fill',type:'fill',source:'bpV5004WeatherShapes',minzoom:3.5,filter:['==',['geometry-type'],'Polygon'],paint:{'fill-color':weatherColorExpr(),'fill-opacity':['case',['==',['get','observed'],true],.14,.08]}});if(!map.getLayer('bp-v5004-weather-shape-line'))map.addLayer({id:'bp-v5004-weather-shape-line',type:'line',source:'bpV5004WeatherShapes',minzoom:3.5,paint:{'line-color':weatherColorExpr(),'line-width':['interpolate',['linear'],['zoom'],3.5,1,8,2.4,14,4],'line-opacity':['case',['==',['get','observed'],true],.86,.55]}});if(!map.getLayer('bp-v5004-weather-point-glow'))map.addLayer({id:'bp-v5004-weather-point-glow',type:'circle',source:'bpV5004WeatherPoints',minzoom:4.5,paint:{'circle-radius':['interpolate',['linear'],['zoom'],4.5,4,9,7,14,11],'circle-color':weatherColorExpr(),'circle-opacity':['case',['==',['get','observed'],true],.18,.10],'circle-blur':.8}});if(!map.getLayer('bp-v5004-weather-points'))map.addLayer({id:'bp-v5004-weather-points',type:'circle',source:'bpV5004WeatherPoints',minzoom:4.5,paint:{'circle-radius':['interpolate',['linear'],['zoom'],4.5,1.8,9,3.5,14,6],'circle-color':weatherColorExpr(),'circle-opacity':['case',['==',['get','observed'],true],.9,.56],'circle-stroke-color':'#eefcff','circle-stroke-width':['interpolate',['linear'],['zoom'],4.5,.25,12,1],'circle-stroke-opacity':.72}});setLiveContextVisibility(liveContextVisible);bindLiveContextInteraction();setTimeout(loadLiveWeather,80)}catch(e){console.warn('live context layer install',e)}};if(map.loaded())install();else map.once('load',install)}
async function loadLiveWeather(){if(mapInteracting){deferredWork.set('live-weather',loadLiveWeather);return}const b=$('toggleLiveContext');try{const d=await rpc('bridgepoint_public_weather_bootstrap_v5004',{},3500);const map=world?.map;if(!map)return;if(d?.fresh!==true){map.getSource('bpV5004WeatherPoints')?.setData({type:'FeatureCollection',features:[]});map.getSource('bpV5004WeatherShapes')?.setData({type:'FeatureCollection',features:[]});if(b){b.textContent='LIVE';b.title='Live context cache is stale; map events hidden'}setText('liveLegendCount','STALE');setText('liveLegendTime','Cache expired · live events hidden until the source refresh recovers');return}const c=weatherCollections(d.items||[]);map.getSource('bpV5004WeatherPoints')?.setData(c.points);map.getSource('bpV5004WeatherShapes')?.setData(c.shapes);if(b){b.textContent='LIVE';b.title=(d.items?.length||0)+' fresh source-labelled weather/hazard events · refreshed '+new Date(d.generated_at).toLocaleTimeString()}setText('liveLegendCount',(d.items?.length||0)+' EVENTS');setText('liveLegendTime','Fresh '+new Date(d.generated_at).toLocaleTimeString()+' · solid = observed/source event · faded = alert or forecast')}catch(e){if(b)b.title='Live context refresh retry · '+String(e.message||e)}}
